ALTER TABLE public.store_settings ADD COLUMN share_cart_enabled boolean NOT NULL DEFAULT false, ADD COLUMN dine_in_enabled boolean NOT NULL DEFAULT false, ADD COLUMN whatsapp_number text NOT NULL DEFAULT '';
ALTER TABLE public.products ADD COLUMN cost numeric NOT NULL DEFAULT 0;
ALTER TABLE public.orders ADD COLUMN table_id uuid, ADD COLUMN people integer NOT NULL DEFAULT 1;
CREATE TABLE public.dining_tables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, active boolean NOT NULL DEFAULT true, session_started_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.dining_tables TO authenticated;
GRANT ALL ON public.dining_tables TO service_role;
ALTER TABLE public.dining_tables ENABLE ROW LEVEL SECURITY;
CREATE POLICY director_tables ON public.dining_tables FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY staff_tables_read ON public.dining_tables FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'staff'));
CREATE TABLE public.waiter_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), table_id uuid NOT NULL REFERENCES public.dining_tables(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('garcom','conta')), created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
GRANT SELECT, UPDATE ON public.waiter_calls TO authenticated;
GRANT ALL ON public.waiter_calls TO service_role;
ALTER TABLE public.waiter_calls ENABLE ROW LEVEL SECURITY;
CREATE POLICY team_calls_read ON public.waiter_calls FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE POLICY team_calls_update ON public.waiter_calls FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE TABLE public.shared_carts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), items jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.shared_carts TO service_role;
ALTER TABLE public.shared_carts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.checkout_drafts (phone text PRIMARY KEY, customer_name text NOT NULL DEFAULT '', total numeric NOT NULL DEFAULT 0, items jsonb NOT NULL DEFAULT '[]', converted boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.checkout_drafts TO authenticated;
GRANT ALL ON public.checkout_drafts TO service_role;
ALTER TABLE public.checkout_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY director_drafts ON public.checkout_drafts FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));